mapper.select:
select si.id id,si.sign_type signType,si.org_id orgId,si.org_name orgName,si.user_id userId,si.user_name userName,si.sign_time signTime,si.customer_num customerNum,
si.sign_desc signDesc,si.landmark landmark,si.address address,si.latitude latitude,si.longitude longitude,
count(si.user_id) signNum,ui.img img from  sign_info si LEFT JOIN user_info ui on si.user_id=ui.user_id
where DATE(si.sign_time)=DATE(#{signTime,jdbcType=DATE}) and
si.org_id = #{orgId,jdbcType=BIGINT}
group BY si.user_id ORDER BY si.sign_time DESC;

select ui.user_id userId,ui.user_name userName,ui.img img from user_info ui LEFT JOIN bus_user_role bur on ui.user_id=bur.user_id
where bur.role_id in(2,17) and ui.user_id not in(select user_id from sign_info where org_id= #{orgId,jdbcType=BIGINT}
and DATE(#{signTime,jdbcType=DATE})=DATE(sign_time))  and ui.org_id= #{orgId,jdbcType=BIGINT} GROUP BY ui.user_id
